// Parse the AI response
const response = $input.first().json.text
let parsed;

try {
  parsed = JSON.parse(response);
} catch (e) {
  // If parsing fails, try to extract JSON from the response
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Could not parse AI response as JSON');
  }
}

// Add the parsed response to the existing data
return parsed;

// Input text
const positionText = $input.first().json.result.content[0].text;

// Parse coordinates
const regex = /X=([-+]?\d*\.?\d+),?\s*Y=([-+]?\d*\.?\d+),?\s*Z=([-+]?\d*\.?\d+)/i;
const match = positionText.match(regex);

if (match) {
  const worldX = parseFloat(match[1]);
  const worldY = parseFloat(match[2]);
  const worldZ = parseFloat(match[3]);

  // Generate BlueMap tile path (based on your filesystem structure)
  const zoom = 0;           // Zoom level
  const tileSize = 512;     // BlueMap tile size at zoom 0
  const tileX = Math.floor(worldX / tileSize);
  const tileZ = Math.floor(worldZ / tileSize);

  // Build the correct BlueMap URL based on your structure
  const tileUrl = `http://minecraft-250712.kodelab.dev:8100/maps/world/tiles/${zoom}/x${tileX}/z${tileZ}.prbm.gz`;

  return {
    json: {
      worldX: worldX,
      worldY: worldY,
      worldZ: worldZ,
      tileX: tileX,
      tileZ: tileZ,
      zoom: zoom,
      tileUrl: tileUrl,
      tilePath: `${zoom}/x${tileX}/z${tileZ}.prbm.gz`
    }
  };
} else {
  return {
    json: {
      error: "Could not parse position",
      originalText: positionText
    }
  };
}

